mapper.select:
SELECT  AS id, status, claim_epoch AS claimEpoch,
NULLerror_code AS errorCode
FROM 
WHERE enterprise_id=#{enterpriseId} AND warehouse_id=#{warehouseId} AND status=#{status}
AND  > #{page.id}
ORDER BY  LIMIT #{page.fetchLimit}

mapper.update:
UPDATE  SET status='PENDING', retry_base_epoch=claim_epoch,
    lease_until=NULL, next_attempt_at=#{now}, updated_at=#{now}
WHERE enterprise_id=#{enterpriseId} AND warehouse_id=#{warehouseId} AND =#{messageId}
  AND status='ISOLATED' AND claim_epoch=#{epoch}
